from collections import deque
def fired_at(events, n=3, win=60):
    q = deque()
    for e in events:
        t = e['ts']
        q.append(t)
        while t - q[0] > win:
            q.popleft()
        if len(q) >= n: return t
print(fired_at([{'ts': t} for t in (10, 80, 100, 130)]))

